                "let ok=Boolean(HMIRuntime.Tags(\"PilzDiag_DataValid\").Read());" +
                "if(!ok){return \"DATA INVALID\";}" +
                "let v=Boolean(HMIRuntime.Tags(\"" + valueTag + "\").Read());" +
                "return v?\"" + trueText + "\":\"" + falseText + "\";");
        }

