        private static void ConfigureSettingsExternalWashDataSource(
            HmiScreen screen, int left, int top, Color cardBorder)
        {
            HmiRectangle back = GetOrCreate<HmiRectangle>(screen,
                "REV37_SettingsWash_Badge_DataSource_Back");
