            ConfigureNumericDynamization(text, "Text", "",
                "let q=Boolean(HMIRuntime.Tags(\"Network_HMI_OK\").Read());" +
                "return q?\"PLC / HMI ONLINE\":\"NO DATA / OFFLINE\";");
            ConfigureNumericDynamization(back, "BackColor", "",
