            ConfigureDiagnosticsStatusRow(screen, "IOLink3", "REV12_Label_NetworkIOLink3OK", "REV12_Value_NetworkIOLink3OK",
                "IO-Link island 3", "Network_IOLink3_OK", 45, 375, 270, "ONLINE", "OFFLINE", Green, Red, true);
